#!/bin/sh
# llama-server with the Orin Nano's SM count and compute capability, so kernels split work as on the Jetson.
GGML_CUDA_NSM=8 GGML_CUDA_CC=870 exec ~/qdrant-robot-box/llama.cpp/build/bin/llama-server "$@"
