         info.devices[id].smpb       = prop.sharedMemPerBlock;
         info.devices[id].warp_size  = prop.warpSize;

@@ -341,7 +341,7 @@ static ggml_cuda_device_info ggml_cuda_init() {
                       device_vram_mib);
 #else
         info.devices[id].smpbo = prop.sharedMemPerBlockOptin;
